closed_interface_proposal.types:
type Domain = "health" | "location" | "device_usage";
type FailureCode = "invalid_request" | "scope_not_authorized" | "scope_binding_mismatch" | "owned_handoff_closed" | "source_schema_unavailable" | "record_identity_conflict" | "revision_conflict" | "restoration_fenced" | "storage_unavailable" | "cleanup_unacknowledged" | "busy";
type FixedFailure = Readonly<{_tag:"RepositoryFailure";code:FailureCode}>;
type CommitDecision = "committed" | "definitely_not_committed" | "ambiguous";
interface OwnedCommand { readonly commandBrand: unique symbol }
interface OwnedSnapshot { readonly snapshotBrand: unique symbol }
interface OwnedPlan { readonly planBrand: unique symbol }
interface OwnedReceipt { readonly receiptBrand: unique symbol }
interface CapturedOriginalLifetime { isLive(): boolean; readonly closed: Effect.Effect<void> }
interface Binding { readonly dataset:string;readonly source:string;readonly sourceRevision:string;readonly domain:Domain;readonly purpose:string;readonly destination:string;readonly caller:string;readonly grantRevision:string;readonly externalSuppressionRevision:string }
interface CurrentAuthority { check(binding:Binding,phase:"before_metadata"|"before_read"|"before_prepare"|"before_commit"|"after_commit"|"assert_current"):Effect.Effect<void,FixedFailure> }
interface AuthorizedSourceView { read(command:unknown,ticket:unknown):Effect.Effect<string|null,FixedFailure> }
interface PlanIssuer { issue(command:unknown,primitiveClosedPlan:unknown):OwnedPlan|null }
interface CommitHost { withTransaction<A>(command:OwnedCommand,lifetime:CapturedOriginalLifetime,use:(snapshot:OwnedSnapshot,issuer:PlanIssuer)=>Effect.Effect<A,FixedFailure>):Effect.Effect<A,FixedFailure>; commit(command:OwnedCommand,plan:OwnedPlan):Effect.Effect<CommitDecision,FixedFailure> }
interface RepositoryOperation { run(primitiveRequest:unknown):Effect.Effect<OwnedReceipt,FixedFailure>; inspect(receipt:unknown):Readonly<{decision:CommitDecision;cleanupAcknowledged:true}>|null }
interface RepositoryFactory { create(capturedTrustedPorts:TrustedPorts):Effect.Effect<RepositoryOperation,FixedFailure,Scope.Scope> }
